`timescale 1ns / 1ps

module ALU(
    input[31:0] A, B,
    input[3:0] Control,
    output[31:0] res,
    output zero, overflow
);

    parameter ALU_ADD  = 4'b0001;
    parameter ALU_SUB  = 4'b0010;
    parameter ALU_AND  = 4'b0011;
    parameter ALU_OR   = 4'b0100;
    parameter ALU_XOR  = 4'b0101;
    parameter ALU_SLL  = 4'b0110;
    parameter ALU_SRL  = 4'b0111;
    parameter ALU_SLT  = 4'b1000;
    parameter ALU_SLTU = 4'b1001;
    parameter ALU_SRA  = 4'b1010;
    parameter ALU_Ap4  = 4'b1011;
    parameter ALU_Bout = 4'b1100;

    wire[31:0] res_ADD  = A + B;
    wire[31:0] res_SUB  = A - B;
    wire[31:0] res_AND  = A & B;
    wire[31:0] res_OR   = A | B;
    wire[31:0] res_XOR  = A ^ B;
    wire[31:0] res_SLL  = A << B[4:0];
    wire[31:0] res_SRL  = A >> B[4:0];
    wire[31:0] res_SLT  = ($signed(A) < $signed(B)) ? 32'd1 : 32'd0;
    wire[31:0] res_SLTU = (A < B) ? 32'd1 : 32'd0;
    wire[31:0] res_SRA  = $signed(A) >>> B[4:0];
    wire[31:0] res_Ap4  = A + 32'd4;
    wire[31:0] res_Bout = B;

    assign res = {32{Control == ALU_ADD}}  & res_ADD  |
                 {32{Control == ALU_SUB}}  & res_SUB  |
                 {32{Control == ALU_AND}}  & res_AND  |
                 {32{Control == ALU_OR}}   & res_OR   |
                 {32{Control == ALU_XOR}}  & res_XOR  |
                 {32{Control == ALU_SLL}}  & res_SLL  |
                 {32{Control == ALU_SRL}}  & res_SRL  |
                 {32{Control == ALU_SLT}}  & res_SLT  |
                 {32{Control == ALU_SLTU}} & res_SLTU |
                 {32{Control == ALU_SRA}}  & res_SRA  |
                 {32{Control == ALU_Ap4}}  & res_Ap4  |
                 {32{Control == ALU_Bout}} & res_Bout ;

    assign zero = ~|res;

    assign overflow = (Control == ALU_ADD) ? (~(A[31] ^ B[31]) & (res[31] ^ A[31])) :
                      (Control == ALU_SUB) ? ((A[31] ^ B[31]) & (res[31] ^ A[31])) :
                      1'b0;

endmodule

`timescale 1ns / 1ps

module ImmGen(
            input  wire [2:0] ImmSel,
            input  wire [31:0] inst_field,
            output[31:0] Imm_out
    );
    parameter Imm_type_I = 3'b001;
    parameter Imm_type_B = 3'b010;
    parameter Imm_type_J = 3'b011;
    parameter Imm_type_S = 3'b100;
    parameter Imm_type_U = 3'b101;

    wire[31:0] Imm_I = {{21{inst_field[31]}}, inst_field[30:20]};
    wire[31:0] Imm_B = {{20{inst_field[31]}}, inst_field[7], inst_field[30:25],
                        inst_field[11:8], 1'b0};
    wire[31:0] Imm_J = {{12{inst_field[31]}}, inst_field[19:12], inst_field[20],
                        inst_field[30:21], 1'b0};
    wire[31:0] Imm_S = {{21{inst_field[31]}}, inst_field[30:25], inst_field[11:7]};
    wire[31:0] Imm_U = {inst_field[31:12], 12'b0};

    assign Imm_out = {32{ImmSel == Imm_type_I}} & Imm_I |
                     {32{ImmSel == Imm_type_B}} & Imm_B |
                     {32{ImmSel == Imm_type_J}} & Imm_J |
                     {32{ImmSel == Imm_type_S}} & Imm_S |
                     {32{ImmSel == Imm_type_U}} & Imm_U ;
endmodule

