module     Regs(input clk,
				input rst,
				input [4:0] R_addr_A, 
				input [4:0] R_addr_B, 
				input [4:0] Wt_addr, 
				input [31:0]Wt_data, 
				input L_S, 
				output [31:0] rdata_A, 
				output [31:0] rdata_B,
				input [4:0] Debug_addr,         // debug address
				output[31:0] Debug_regs        // debug data
			  );

	reg [31:0] register [1:31]; 				// r1 - r31
	integer i;

	// synchronous write / reset
	always @(posedge clk or posedge rst)
		if (rst) begin
			for (i = 1; i < 32; i = i + 1)
				register[i] <= 32'b0;
		end
		else if (L_S && (Wt_addr != 5'b0))
			register[Wt_addr] <= Wt_data;

	// write-through read: a register written this cycle reads back the new value
	assign rdata_A = (R_addr_A == 5'b0) ? 32'b0 :
	                 (L_S && (Wt_addr == R_addr_A)) ? Wt_data : register[R_addr_A];
	assign rdata_B = (R_addr_B == 5'b0) ? 32'b0 :
	                 (L_S && (Wt_addr == R_addr_B)) ? Wt_data : register[R_addr_B];

	assign Debug_regs = (Debug_addr == 5'b0) ? 32'b0 : register[Debug_addr];

endmodule

`timescale 1ns / 1ps

module RAM_B(
    input [31:0] addra,
    input clka,      // normal clock
    input[31:0] dina,
    input wea, 
    output[31:0] douta,
    input[2:0] mem_u_b_h_w
);

    reg[7:0] data[0:127];

    initial	begin
        $readmemh("ram.mem", data);
    end

    wire addr_valid = addra[31:7] == 25'b0;
    wire[6:0] addr = addra[6:0];

    // mem_u_b_h_w[1]=1 -> word, mem_u_b_h_w[0]=1 -> halfword, otherwise byte
    wire wr_word = mem_u_b_h_w[1];
    wire wr_half = mem_u_b_h_w[0];

    always @(posedge clka) begin
        if (wea && addr_valid) begin
            if (wr_word) begin
                data[addr]     <= dina[7:0];
                data[addr + 1] <= dina[15:8];
                data[addr + 2] <= dina[23:16];
                data[addr + 3] <= dina[31:24];
            end
            else if (wr_half) begin
                data[addr]     <= dina[7:0];
                data[addr + 1] <= dina[15:8];
            end
            else begin
                data[addr]     <= dina[7:0];
            end
        end
    end

    // combinational read; mem_u_b_h_w[2]=1 -> unsigned (zero-extend)
    wire[31:0] rd_word = {data[addr + 3], data[addr + 2], data[addr + 1], data[addr]};
    wire[31:0] rd_half = mem_u_b_h_w[2] ? {16'b0, data[addr + 1], data[addr]} :
                         {{16{data[addr + 1][7]}}, data[addr + 1], data[addr]};
    wire[31:0] rd_byte = mem_u_b_h_w[2] ? {24'b0, data[addr]} :
                         {{24{data[addr][7]}}, data[addr]};

    assign douta = ~addr_valid ? 32'b0 :
                   wr_word     ? rd_word :
                   wr_half     ? rd_half :
                                 rd_byte;

endmodule

