// TODO: implement — IF/ID pipeline register
// On reset: clear IR_ID and PCurrent_ID to 0.
// When EN is asserted:
//   - If Data_stall: hold current values (stall the pipeline stage)
//   - Else if flush: replace IR_ID with NOP (32'h00000013), hold PCurrent_ID
//   - Else: latch new instruction IR and program counter PCOUT
// When EN is deasserted: hold current values.

args.new_string:
always @(posedge clk or posedge rst)
    if (rst) begin
        IR_ID       <= 32'b0;
        PCurrent_ID <= 32'b0;
    end
    else if (EN) begin
        if (Data_stall) begin
            IR_ID       <= IR_ID;
            PCurrent_ID <= PCurrent_ID;
        end
        else if (flush) begin
            IR_ID       <= 32'h00000013;    // NOP: addi x0, x0, 0
            PCurrent_ID <= PCurrent_ID;
        end
        else begin
            IR_ID       <= IR;
            PCurrent_ID <= PCOUT;
        end
    end

