`timescale 1ps/1ps

module HazardDetectionUnit(
    input clk,
    input Branch_ID, rs1use_ID, rs2use_ID,
    input[1:0] hazard_optype_ID,
    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
    output PC_EN_IF, reg_FD_EN, reg_FD_stall, reg_FD_flush,
        reg_DE_EN, reg_DE_flush, reg_EM_EN, reg_EM_flush, reg_MW_EN,
    output forward_ctrl_ls,
    output[1:0] forward_ctrl_A, forward_ctrl_B
);
    // hazard_optype of the instruction in EX / MEM stage
    reg[1:0] hazard_optype_EXE, hazard_optype_MEM;
    always @(posedge clk) begin
        hazard_optype_EXE <= hazard_optype_ID;
        hazard_optype_MEM <= hazard_optype_EXE;
    end

    wire exe_writes  = hazard_optype_EXE != 2'b00;
    wire mem_writes  = hazard_optype_MEM != 2'b00;

    // the instruction in EX writes a register that the ID instruction reads:
    // its result is not ready yet, stall one cycle then forward from MEM
    wire stall = exe_writes & (rd_EXE != 5'b0) &
                 ((rs1use_ID & (rs1_ID == rd_EXE)) |
                  (rs2use_ID & (rs2_ID == rd_EXE)));

    assign PC_EN_IF     = ~stall;
    assign reg_FD_EN    = 1'b1;
    assign reg_FD_stall = stall;
    assign reg_FD_flush = Branch_ID & ~stall;
    assign reg_DE_EN    = 1'b1;
    assign reg_DE_flush = stall;
    assign reg_EM_EN    = 1'b1;
    assign reg_EM_flush = 1'b0;
    assign reg_MW_EN    = 1'b1;

    // forward from MEM stage to the ID-stage comparator / branch / ALU latches
    wire fwd_A = mem_writes & (rd_MEM != 5'b0) & rs1use_ID & (rs1_ID == rd_MEM);
    wire fwd_B = mem_writes & (rd_MEM != 5'b0) & rs2use_ID & (rs2_ID == rd_MEM);

    assign forward_ctrl_A = fwd_A ? 2'b01 : 2'b00;
    assign forward_ctrl_B = fwd_B ? 2'b01 : 2'b00;

    // forward MEM result to the store data of the instruction in EX
    assign forward_ctrl_ls = mem_writes & (rd_MEM != 5'b0) & (rd_MEM == rs2_EXE);

endmodule

`timescale 1ns / 1ps
// Testbench: run lab1 core on rom.mem/ram.mem, check WB-stage writes.
module lab1_tb;
    reg clk, rst;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #4 rst = 0;
    end
    always #1 clk = ~clk;

    integer errors = 0;
    integer checks = 0;

    // expected writes: checked when (PC_WB, rd) matches and value is compared
    task check(input [31:0] pc, input [4:0] rd, input [31:0] val);
        begin
            checks = checks + 1;
            if (core.reg_MEM_WB.PCurrent_WB == pc && core.reg_MEM_WB.RegWrite_WB &&
                core.reg_MEM_WB.rd_WB == rd) begin
                if (core.mux_WB.o !== val) begin
                    errors = errors + 1;
                    $display("FAIL PC=%h rd=x%0d got=%h exp=%h", pc, rd, core.mux_WB.o, val);
                end
            end
        end
    endtask

    // monitor every WB write, record latest write per PC
    reg [31:0] wb_val [0:1023];
    reg [4:0]  wb_rd  [0:1023];
    reg        wb_hit [0:1023];
    always @(posedge clk) begin
        if (!rst && core.reg_MEM_WB.RegWrite_WB && core.reg_MEM_WB.rd_WB != 0) begin
            wb_val[core.reg_MEM_WB.PCurrent_WB[9:0]] <= core.mux_WB.o;
            wb_rd [core.reg_MEM_WB.PCurrent_WB[9:0]] <= core.reg_MEM_WB.rd_WB;
            wb_hit[core.reg_MEM_WB.PCurrent_WB[9:0]] <= 1'b1;
        end
    end

    task expect(input [31:0] pc, input [4:0] rd, input [31:0] val);
        begin
            checks = checks + 1;
            if (wb_hit[pc[9:0]] !== 1'b1) begin
                errors = errors + 1;
                $display("FAIL PC=%h: no write to x%0d observed", pc, rd);
            end
            else if (wb_rd[pc[9:0]] !== rd || wb_val[pc[9:0]] !== val) begin
                errors = errors + 1;
                $display("FAIL PC=%h exp x%0d=%h got x%0d=%h", pc, rd, val,
                         wb_rd[pc[9:0]], wb_val[pc[9:0]]);
            end
        end
    endtask

    integer i;
    initial begin
        for (i = 0; i < 1024; i = i + 1) wb_hit[i] = 0;
        #2000;
        expect(32'h04, 5'd2, 32'h00000008);
        expect(32'h08, 5'd4, 32'h00000010);
        expect(32'h0C, 5'd1, 32'h00000018);
        expect(32'h10, 5'd1, 32'h00000017);
        expect(32'h14, 5'd5, 32'h00000014);
        expect(32'h18, 5'd6, 32'hFFFF0000);
        expect(32'h1C, 5'd7, 32'h0FFF0000);
        expect(32'h20, 5'd1, 32'h00000008);
        expect(32'h24, 5'd1, 32'h00000000);
        expect(32'h28, 5'd1, 32'h00000018);
        expect(32'h2C, 5'd1, 32'h00000018);
        expect(32'h30, 5'd1, 32'h00001000);
        expect(32'h34, 5'd1, 32'h00000000);
        expect(32'h38, 5'd1, 32'h00000001);
        expect(32'h3C, 5'd1, 32'h00FFFF00);
        expect(32'h40, 5'd1, 32'hFFFFFF00);
        expect(32'h44, 5'd1, 32'h000FFF00);
        expect(32'h48, 5'd1, 32'h00000000);
        expect(32'h4C, 5'd1, 32'h00000001);
        expect(32'h54, 5'd1, 32'hFFFFFFFD);
        expect(32'h58, 5'd1, 32'h00000000);
        expect(32'h5C, 5'd1, 32'h0000001F);
        expect(32'h60, 5'd1, 32'h0000001F);
        expect(32'h64, 5'd1, 32'h00000000);
        expect(32'h68, 5'd1, 32'h00000020);
        expect(32'h6C, 5'd1, 32'h00000004);
        expect(32'h70, 5'd1, 32'hFFFFFFF0);
        expect(32'h74, 5'd1, 32'h00000001);
        expect(32'h78, 5'd1, 32'h00000001);
        expect(32'hE8, 5'd1, 32'h00004000);
        expect(32'hEC, 5'd1, 32'h000000F0);
        expect(32'hF8, 5'd8, 32'hFF000F0F);
        expect(32'h100, 5'd1, 32'hFF000F0F);
        expect(32'h108, 5'd1, 32'h00000F0F);
        expect(32'h110, 5'd1, 32'h0000000F);
        expect(32'h114, 5'd1, 32'hFFFFFF00);
        expect(32'h118, 5'd1, 32'h0000FF00);
        expect(32'h11C, 5'd1, 32'hFFFFFFFF);
        expect(32'h120, 5'd1, 32'h000000FF);
        expect(32'h124, 5'd1, 32'hFFFF0124);
        expect(32'h128, 5'd1, 32'h0000012C);
        if (errors == 0) $display("LAB1 PASS: %0d checks OK", checks);
        else             $display("LAB1 FAIL: %0d errors / %0d checks", errors, checks);
        $finish;
    end

endmodule

