    localparam hazard_optype_ALU = 2'd1;
    localparam hazard_optype_LOAD = 2'd2;
    localparam hazard_optype_STORE = 2'd3;

    // TODO: implement — detect data hazards, generate forwarding controls,
    // stall signals, and flush signals
    assign PC_EN_IF = 1'b1;
    assign reg_FD_stall = 1'b0;
    assign reg_FD_flush = 1'b0;
    assign reg_DE_flush = 1'b0;

    assign forward_ctrl_A = 2'b0;
    assign forward_ctrl_B = 2'b0;

    assign forward_ctrl_ls = 1'b0;

