module    REG_IF_ID(input clk,                                      //IF/ID Latch
                    input rst,
                    input EN,                                       //流水寄存器使能
                    input Data_stall,                               //数据竞争等待
                    input flush,                                    //控制竞争清除并等待
                    input [31:0] PCOUT,                             //指令存储器指针
                    input [31:0] IR,                                //指令存储器输出

                    output reg[31:0] IR_ID,                         //取指锁存
                    output reg[31:0] PCurrent_ID,                   //当前存在指令地址
                    output reg isFlushed
                );

//reg[31:0]PCurrent_ID,IR_ID;
    always @(posedge clk or posedge rst) begin
        // TODO: implement — pipeline register IF/ID
        // On reset: IR_ID <= NOP (32'h00000013), PCurrent_ID <= 0, isFlushed <= 0
        // On Data_stall: hold current values
        // On flush: insert NOP, set isFlushed
        // Otherwise: latch IR and PCOUT
        if(rst) begin
            IR_ID <= 32'h00000013;
            PCurrent_ID <= 32'h00000000;
            isFlushed <= 0;
        end
        else if(EN) begin
            IR_ID <= 32'h00000013;
            PCurrent_ID <= 32'h00000000;
            isFlushed <= 0;
        end
    end

endmodule`timescale 1ns / 1ps
