`timescale 1ns / 1ps

module CSRRegs(
    input clk, rst,
    input[11:0] raddr, waddr,
    input[31:0] wdata,
    input csr_w,
    input[1:0] csr_wsc_mode,
    output[31:0] rdata,
    output[31:0] mstatus
);
    // You may need to modify this module for better efficiency

    reg[31:0] CSR [0:15];

    // Address mapping. The address is 12 bits, but only 4 bits are used in this module.
    wire raddr_valid = raddr[11:7] == 5'h6 && raddr[5:3] == 3'h0;
    wire[3:0] raddr_map = (raddr[6] << 3) + raddr[2:0];
    wire waddr_valid = waddr[11:7] == 5'h6 && waddr[5:3] == 3'h0;
    wire[3:0] waddr_map = (waddr[6] << 3) + waddr[2:0];

    assign mstatus = CSR[0];

    // write value according to write/set/clear mode
    wire[31:0] wdata_wsc = csr_wsc_mode == 2'b01 ? wdata :
                           csr_wsc_mode == 2'b10 ? (CSR[waddr_map] | wdata) :
                           csr_wsc_mode == 2'b11 ? (CSR[waddr_map] & ~wdata) :
                           wdata;

    // CSR read logic, with write-through for a write in flight this cycle
    assign rdata = ~raddr_valid ? 32'b0 :
                   (csr_w && waddr_valid && (waddr_map == raddr_map)) ? wdata_wsc :
                   CSR[raddr_map];

    // CSR write logic (write/set/clear modes)
    always@(posedge clk or posedge rst) begin
        if(rst) begin
			CSR[0] <= 32'h88;
			CSR[1] <= 0;
			CSR[2] <= 0;
			CSR[3] <= 0;
			CSR[4] <= 32'hfff;
			CSR[5] <= 0;
			CSR[6] <= 0;
			CSR[7] <= 0;
			CSR[8] <= 0;
			CSR[9] <= 0;
			CSR[10] <= 0;
			CSR[11] <= 0;
			CSR[12] <= 0;
			CSR[13] <= 0;
			CSR[14] <= 0;
			CSR[15] <= 0;
		end
        else if (csr_w && waddr_valid) begin
            CSR[waddr_map] <= wdata_wsc;
        end
    end
endmodule

`timescale 1ns / 1ps

module ExceptionUnit(
    input clk, rst,
    input csr_rw_in,
    // write/set/clear (funct bits from instruction)
    input[1:0] csr_wsc_mode_in,
    input csr_w_imm_mux,
    input[11:0] csr_rw_addr_in,
    input[31:0] csr_w_data_reg,
    input[4:0] csr_w_data_imm,
    output[31:0] csr_r_data_out,

    input interrupt,
    input illegal_inst,
    input l_access_fault,
    input s_access_fault,
    input ecall_m,

    input mret,

    input[31:0] epc_cur,
    input[31:0] epc_next,
    // faulting instruction (WB) and faulting address (WB ALU result) for mtval
    input[31:0] exp_inst,
    input[31:0] exp_addr,
    output[31:0] PC_redirect,
    output redirect_mux,

    output reg_FD_flush, reg_DE_flush, reg_EM_flush, reg_MW_flush, 
    output RegWrite_cancel,
    output MemWrite_cancel
);
    // According to the diagram, design the Exception Unit
    // You can modify any code in this file if needed!
    reg[11:0] csr_waddr;
    reg[31:0] csr_wdata;
    reg csr_w;
    reg[1:0] csr_wsc;
    wire[11:0] csr_raddr;

    wire[31:0] mstatus;
    wire[31:0] csr_rdata;

    localparam ADDR_MSTATUS = 12'h300;
    localparam ADDR_MTVEC   = 12'h305;
    localparam ADDR_MEPC    = 12'h341;
    localparam ADDR_MCAUSE  = 12'h342;
    localparam ADDR_MTVAL   = 12'h343;

    localparam MCAUSE_INT    = 32'h8000000b;
    localparam MCAUSE_ECALL  = 32'd11;
    localparam MCAUSE_ILLEGAL= 32'd2;
    localparam MCAUSE_LFAULT = 32'd5;
    localparam MCAUSE_SFAULT = 32'd7;

    // exception request sequencer: writes mepc/mcause/mtval/mstatus over
    // four consecutive cycles after the trap is taken
    reg[2:0] exp_state;
    reg[31:0] exp_mepc, exp_mcause, exp_mtval, exp_mstatus;
    reg mret_pending;

    wire exp_busy = exp_state != 3'd0;

    wire sync_exp = illegal_inst | ecall_m | l_access_fault | s_access_fault;
    wire take_int = interrupt & mstatus[3] & ~sync_exp & ~exp_busy & ~mret & ~mret_pending;
    wire exp_detect = (sync_exp | take_int) & ~exp_busy;
    wire mret_eff = mret & ~exp_detect;

    wire[31:0] cause = take_int     ? MCAUSE_INT    :
                       illegal_inst ? MCAUSE_ILLEGAL :
                       ecall_m      ? MCAUSE_ECALL  :
                       l_access_fault ? MCAUSE_LFAULT : MCAUSE_SFAULT;
    wire[31:0] tval = illegal_inst ? exp_inst :
                      (l_access_fault | s_access_fault) ? exp_addr : 32'b0;
    wire[31:0] epc  = take_int ? epc_next : epc_cur;

    // mstatus on trap entry: MPP<-11, MPIE<-MIE, MIE<-0
    wire[31:0] mstatus_trap = {mstatus[31:13], 2'b11, mstatus[10:8],
                               mstatus[3], mstatus[6:4], 1'b0, mstatus[2:0]};
    // mstatus on mret: MPP<-00, MPIE<-1, MIE<-MPIE
    wire[31:0] mstatus_restore = {mstatus[31:13], 2'b00, mstatus[10:8],
                                  1'b1, mstatus[6:4], mstatus[7], mstatus[2:0]};

    // normal CSR write request (registered from MEM stage, cancelled if the
    // pipeline is flushed by a trap taken this cycle)
    always@(posedge clk or posedge rst) begin
        if (rst) begin
            csr_w     <= 1'b0;
            csr_waddr <= 12'b0;
            csr_wdata <= 32'b0;
            csr_wsc   <= 2'b0;
        end
        else begin
            csr_w     <= csr_rw_in & ~exp_detect;
            csr_waddr <= csr_rw_addr_in;
            csr_wdata <= csr_w_imm_mux ? {27'b0, csr_w_data_imm} : csr_w_data_reg;
            csr_wsc   <= csr_wsc_mode_in;
        end
    end

    // trap sequencer
    always@(posedge clk or posedge rst) begin
        if (rst) begin
            exp_state    <= 3'd0;
            exp_mepc     <= 32'b0;
            exp_mcause   <= 32'b0;
            exp_mtval    <= 32'b0;
            exp_mstatus  <= 32'b0;
            mret_pending <= 1'b0;
        end
        else begin
            if (mret_eff)      mret_pending <= 1'b1;
            else if (mret_wr)  mret_pending <= 1'b0;

            case (exp_state)
                3'd0: if (exp_detect) begin
                        exp_state   <= 3'd1;
                        exp_mepc    <= epc;
                        exp_mcause  <= cause;
                        exp_mtval   <= tval;
                        exp_mstatus <= mstatus_trap;
                    end
                3'd1: exp_state <= 3'd2;
                3'd2: exp_state <= 3'd3;
                3'd3: exp_state <= 3'd4;
                default: exp_state <= 3'd0;
            endcase
        end
    end

    // CSR write port arbitration: trap sequencer > mret restore > normal CSR write
    wire exp_wr = exp_busy;
    wire mret_wr = mret_pending & ~exp_busy;

    wire[11:0] exp_waddr = exp_state == 3'd1 ? ADDR_MEPC    :
                           exp_state == 3'd2 ? ADDR_MCAUSE  :
                           exp_state == 3'd3 ? ADDR_MTVAL   : ADDR_MSTATUS;
    wire[31:0] exp_wdata = exp_state == 3'd1 ? exp_mepc     :
                           exp_state == 3'd2 ? exp_mcause   :
                           exp_state == 3'd3 ? exp_mtval    : exp_mstatus;

    CSRRegs csr(.clk(clk),.rst(rst),
        .csr_w(exp_wr | mret_wr | csr_w),
        .raddr(csr_raddr),
        .waddr(exp_wr ? exp_waddr : mret_wr ? ADDR_MSTATUS : csr_waddr),
        .wdata(exp_wr ? exp_wdata : mret_wr ? mstatus_restore : csr_wdata),
        .rdata(csr_rdata),.mstatus(mstatus),
        .csr_wsc_mode((exp_wr | mret_wr) ? 2'b01 : csr_wsc));

    // CSR read address: trap vector / return address / normal CSR read
    assign csr_raddr = exp_detect ? ADDR_MTVEC :
                       mret_eff   ? ADDR_MEPC  : csr_rw_addr_in;
    assign csr_r_data_out = csr_rdata;

    assign PC_redirect = csr_rdata;   // mtvec on trap, mepc on mret
    assign redirect_mux = exp_detect | mret_eff;

    assign reg_FD_flush = exp_detect | mret_eff;
    assign reg_DE_flush = exp_detect | mret_eff;
    assign reg_EM_flush = exp_detect | mret_eff;
    assign reg_MW_flush = exp_detect;
    assign RegWrite_cancel = sync_exp;
    assign MemWrite_cancel = s_access_fault;

endmodule

`timescale 1ns / 1ps
// Testbench: lab2 CSR + exceptions. Program loops (jr x0), so each trap is
// taken repeatedly; check all expected (pc, rd, value) writes are observed
// and no unexpected values appear at checked PCs.
module lab2_tb;
    reg clk, rst;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #4 rst = 0;
    end
    always #1 clk = ~clk;

    integer errors = 0;
    integer i;

    // expected tuples (pc, rd, value); each must be seen at least once
    localparam NEXP = 27;
    reg [31:0] exp_pc  [0:NEXP-1];
    reg [4:0]  exp_rd  [0:NEXP-1];
    reg [31:0] exp_val [0:NEXP-1];
    reg        seen    [0:NEXP-1];

    initial begin
        exp_pc[0]=32'h04; exp_rd[0]=2;  exp_val[0]=32'h00000008;
        exp_pc[1]=32'h08; exp_rd[1]=4;  exp_val[1]=32'h00000010;
        exp_pc[2]=32'h0C; exp_rd[2]=5;  exp_val[2]=32'h00000014;
        exp_pc[3]=32'h10; exp_rd[3]=6;  exp_val[3]=32'hFFFF0000;
        exp_pc[4]=32'h14; exp_rd[4]=7;  exp_val[4]=32'h0FFF0000;
        exp_pc[5]=32'h18; exp_rd[5]=1;  exp_val[5]=32'h00000000; // csrrwi old val
        exp_pc[6]=32'h1C; exp_rd[6]=1;  exp_val[6]=32'h00000010; // csrr
        exp_pc[7]=32'h20; exp_rd[7]=1;  exp_val[7]=32'h00000010; // csrrw old val
        exp_pc[8]=32'h24; exp_rd[8]=1;  exp_val[8]=32'hFFFF0000; // csrr
        exp_pc[9]=32'h2C; exp_rd[9]=1;  exp_val[9]=32'h00000078;
        // trap 1: ecall @ 0x38
        exp_pc[10]=32'h78; exp_rd[10]=25; exp_val[10]=32'h00000038;
        exp_pc[11]=32'h7C; exp_rd[11]=27; exp_val[11]=32'h0000000B;
        exp_pc[12]=32'h80; exp_rd[12]=28; exp_val[12]=32'h00001880;
        exp_pc[13]=32'h84; exp_rd[13]=29; exp_val[13]=32'h00000000;
        exp_pc[14]=32'h88; exp_rd[14]=30; exp_val[14]=32'h00000000;
        exp_pc[15]=32'h8C; exp_rd[15]=2;  exp_val[15]=32'h0000003C;
        // trap 2: illegal @ 0x40
        exp_pc[16]=32'h78; exp_rd[16]=25; exp_val[16]=32'h00000040;
        exp_pc[17]=32'h7C; exp_rd[17]=27; exp_val[17]=32'h00000002;
        exp_pc[18]=32'h84; exp_rd[18]=29; exp_val[18]=32'h00000012;
        exp_pc[19]=32'h8C; exp_rd[19]=2;  exp_val[19]=32'h00000044;
        // trap 3: load fault @ 0x4c
        exp_pc[20]=32'h78; exp_rd[20]=25; exp_val[20]=32'h0000004C;
        exp_pc[21]=32'h7C; exp_rd[21]=27; exp_val[21]=32'h00000005;
        exp_pc[22]=32'h84; exp_rd[22]=29; exp_val[22]=32'h00000080;
        exp_pc[23]=32'h8C; exp_rd[23]=2;  exp_val[23]=32'h00000050;
        // trap 4: store fault @ 0x54
        exp_pc[24]=32'h78; exp_rd[24]=25; exp_val[24]=32'h00000054;
        exp_pc[25]=32'h7C; exp_rd[25]=27; exp_val[25]=32'h00000007;
        exp_pc[26]=32'h8C; exp_rd[26]=2;  exp_val[26]=32'h00000058;
        for (i = 0; i < NEXP; i = i + 1) seen[i] = 0;
    end

    // validate handler-PC writes against allowed value sets
    task check_handler(input [31:0] pc, input [4:0] rd, input [31:0] val);
        begin
            case (pc)
                32'h78: if (rd == 25 && !(val==32'h38||val==32'h40||val==32'h4C||val==32'h54)) begin
                            errors=errors+1; $display("FAIL x25=%h at %t", val, $time); end
                32'h7C: if (rd == 27 && !(val==32'hB||val==2||val==5||val==7)) begin
                            errors=errors+1; $display("FAIL x27=%h at %t", val, $time); end
                32'h80: if (rd == 28 && val != 32'h1880) begin
                            errors=errors+1; $display("FAIL x28=%h at %t", val, $time); end
                32'h84: if (rd == 29 && !(val==0||val==32'h12||val==32'h80)) begin
                            errors=errors+1; $display("FAIL x29=%h at %t", val, $time); end
                32'h88: if (rd == 30 && val != 0) begin
                            errors=errors+1; $display("FAIL x30=%h at %t", val, $time); end
            endcase
        end
    endtask

    always @(posedge clk) begin
        if (!rst && core.reg_MEM_WB.RegWrite_WB && core.reg_MEM_WB.rd_WB != 0 &&
            !core.reg_MEM_WB.isFlushed && !core.RegWrite_cancel_exp) begin
            for (i = 0; i < NEXP; i = i + 1)
                if (core.reg_MEM_WB.PCurrent_WB == exp_pc[i] &&
                    core.reg_MEM_WB.rd_WB == exp_rd[i] &&
                    core.mux_WB.o == exp_val[i]) seen[i] <= 1;
            check_handler(core.reg_MEM_WB.PCurrent_WB, core.reg_MEM_WB.rd_WB, core.mux_WB.o);
        end
    end

    initial begin
        #4000;
        for (i = 0; i < NEXP; i = i + 1)
            if (!seen[i]) begin
                errors = errors + 1;
                $display("MISSING PC=%h x%0d=%h", exp_pc[i], exp_rd[i], exp_val[i]);
            end
        if (errors == 0) $display("LAB2 PASS: all %0d expectations observed", NEXP);
        else             $display("LAB2 FAIL: %0d errors", errors);
        $finish;
    end

endmodule

