`timescale 1ns / 1ps

module RAM_B(
    input [31:0] addra,
    input clka,      // normal clock
    input[31:0] dina,
    input wea, 
    output[31:0] douta,
    output [7:0] sim_uart_char_out,
    output sim_uart_char_valid,
    input[2:0] mem_u_b_h_w
);
    localparam SIZE = 256;
    localparam ADDR_LINE = $clog2(SIZE);
    localparam SIM_UART_ADDR = 32'h10000000;

    reg[7:0] data[0:SIZE-1];

    initial	begin
        $readmemh("ram.mem", data);
    end

    wire uart_sel = addra == SIM_UART_ADDR;
    wire ram_sel = addra[31:ADDR_LINE] == {(32-ADDR_LINE){1'b0}};
    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];

    // mem_u_b_h_w[1]=1 -> word, mem_u_b_h_w[0]=1 -> halfword, otherwise byte
    wire wr_word = mem_u_b_h_w[1];
    wire wr_half = mem_u_b_h_w[0];

    // byte-addressable write logic (writes to the simulated UART are excluded)
    always @(posedge clka) begin
        if (wea && ram_sel && !uart_sel) begin
            if (wr_word) begin
                data[addr]     <= dina[7:0];
                data[addr + 1] <= dina[15:8];
                data[addr + 2] <= dina[23:16];
                data[addr + 3] <= dina[31:24];
            end
            else if (wr_half) begin
                data[addr]     <= dina[7:0];
                data[addr + 1] <= dina[15:8];
            end
            else begin
                data[addr]     <= dina[7:0];
            end
        end
    end

    // combinational read; mem_u_b_h_w[2]=1 -> unsigned (zero-extend)
    wire[31:0] rd_word = {data[addr + 3], data[addr + 2], data[addr + 1], data[addr]};
    wire[31:0] rd_half = mem_u_b_h_w[2] ? {16'b0, data[addr + 1], data[addr]} :
                         {{16{data[addr + 1][7]}}, data[addr + 1], data[addr]};
    wire[31:0] rd_byte = mem_u_b_h_w[2] ? {24'b0, data[addr]} :
                         {{24{data[addr][7]}}, data[addr]};

    assign douta = (~ram_sel | uart_sel) ? 32'b0 :
                   wr_word               ? rd_word :
                   wr_half               ? rd_half :
                                           rd_byte;

    // simulated UART output: latch the character of a store to SIM_UART_ADDR
    reg[7:0] uart_char;
    reg uart_valid;
    always @(posedge clka) begin
        if (wea && uart_sel) begin
            uart_char  <= dina[7:0];
            uart_valid <= 1'b1;
        end
        else begin
            uart_valid <= 1'b0;
        end
    end
    assign sim_uart_char_out = uart_char;
    assign sim_uart_char_valid = uart_valid;

endmodule

