// Testbench: run lab3 core on the sort program, capture UART output and
// verify the sorted arrays in RAM afterwards.
module lab3_tb;
    reg clk, rst;
    wire [7:0] uart_char;
    wire uart_valid;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0),
        .sim_uart_char_out(uart_char),
        .sim_uart_char_valid(uart_valid)
    );

    initial begin
        clk = 0;
        rst = 1;
        #4 rst = 0;
    end
    always #1 clk = ~clk;

    // capture UART output
    always @(posedge clk) begin
        if (!rst && uart_valid) $write("%c", uart_char);
    end

    integer i;
    integer errors = 0;
    initial begin
        #4000000;
        $display("");
        // after both sorts, arrays at 0x14 and 0x64 must be 0..19
        for (i = 0; i < 20; i = i + 1) begin
            if ({core.data_ram.data[20+4*i+3], core.data_ram.data[20+4*i+2],
                 core.data_ram.data[20+4*i+1], core.data_ram.data[20+4*i]} !== i) begin
                errors = errors + 1;
                $display("FAIL arr1[%0d] = %h", i, {core.data_ram.data[20+4*i+3],
                    core.data_ram.data[20+4*i+2], core.data_ram.data[20+4*i+1],
                    core.data_ram.data[20+4*i]});
            end
            if ({core.data_ram.data[100+4*i+3], core.data_ram.data[100+4*i+2],
                 core.data_ram.data[100+4*i+1], core.data_ram.data[100+4*i]} !== i) begin
                errors = errors + 1;
                $display("FAIL arr2[%0d] = %h", i, {core.data_ram.data[100+4*i+3],
                    core.data_ram.data[100+4*i+2], core.data_ram.data[100+4*i+1],
                    core.data_ram.data[100+4*i]});
            end
        end
        if (errors == 0) $display("LAB3 PASS: both arrays sorted");
        else             $display("LAB3 FAIL: %0d errors", errors);
        $finish;
    end

endmodule
